stk.exp.ret <- function (ret, hld, k, tol = 1e-8)
{
n <- nrow(ret)
d <- ncol(ret)
res <- matrix(NA, n, d - 1)
for(s in 2:d)
res[, s - 1] <- residuals(lm(ret[, s] ∼ -1 + hld[, , s]))
v <- 1 / calc.spec.var(res, k)
x <- t(hld[, , 1]) %*% (v * hld[, , 1])
x.e <- eigen(x)
x.val <- x.e$values
x.vec <- x.e$vectors
take <- x.val > tol * x.val[1]
x.val <- x.val[take]
x.vec <- x.vec[, take]
stk <- colSums(hld[, , 1] * v * ret[, 1])
stk <- colSums(x.vec * stk) / x.val
stk <- colSums(t(x.vec) * stk)
return(stk)
}
